"""Reusable conversions for Meridian CRM 4.2 legacy storage conventions."""

from datetime import date
from decimal import Decimal, ROUND_HALF_UP
import re
from typing import Union


_LEGACY_DATE_RE = re.compile(r"\d{8}\Z")
_ISO_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}\Z")

Amount = Union[str, int, float, Decimal]


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO format."""
    if yyyymmdd is None or yyyymmdd in {"", "00000000"}:
        return None
    if not isinstance(yyyymmdd, str) or not _LEGACY_DATE_RE.fullmatch(yyyymmdd):
        raise ValueError(f"invalid legacy date: {yyyymmdd!r}")

    converted = date(
        int(yyyymmdd[0:4]),
        int(yyyymmdd[4:6]),
        int(yyyymmdd[6:8]),
    )
    return converted.isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to legacy YYYYMMDD format."""
    if iso is None or iso == "":
        return "00000000"
    if not isinstance(iso, str) or not _ISO_DATE_RE.fullmatch(iso):
        raise ValueError(f"invalid ISO date: {iso!r}")

    converted = date.fromisoformat(iso)
    return converted.strftime("%Y%m%d")


def yn(char: str | None) -> bool:
    """Convert a legacy Y/N character to bool, treating blank as N."""
    if char == "Y":
        return True
    if char in {"N", "", None}:
        return False
    raise ValueError(f"invalid legacy boolean: {char!r}")


def to_minor_units(amount: Amount | None, currency: str | None) -> int:
    """Convert a legacy decimal amount to integer currency minor units."""
    decimal_amount = Decimal(0) if amount is None or amount == "" else Decimal(str(amount))
    currency_code = "USD" if currency is None or currency == "" else currency
    exponent = 0 if currency_code == "JPY" else 2
    scaled = decimal_amount * (Decimal(10) ** exponent)
    return int(scaled.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
